using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 breaking change: discriminator property renamed to "$type".
            // Restore EF Core 8 behaviour for compatibility with existing 500K documents.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 breaking change: id format changed from "EntityName|<key>" to just "<key>".
            // Restore EF Core 8 format so existing documents remain accessible.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyIdValueGenerator>();
        });

        // EF Core 9 removed HasIndex for Cosmos (was a no-op); removed to avoid build error.
    }
}

class Product
{
    public int Id { get; set; }
    public string Sku { get; set; } = default!;
}

